14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    // TODO: Multicall support
36	    if !cmd.is_no_binary_name_set() {
37	        raw_args.next_os(&mut cursor);
38	    }
39	
40	    let mut current_cmd = &*cmd;
41	    let mut pos_index = 1;
42	    let mut is_escaped = false;
43	    let mut next_state = ParseState::ValueDone;
44	    let mut used_args = Vec::<clap::Id>::new();
45	    while let Some(arg) = raw_args.next(&mut cursor) {
46	        let current_state = next_state;
47	        next_state = ParseState::ValueDone;
48	        debug!(
49	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
50	            arg.to_value_os(),
51	        );
52	        if cursor == target_cursor {
53	            return complete_arg(
54	                &arg,
55	                current_cmd,
56	                current_dir,
57	                pos_index,
58	                is_escaped,
59	                current_state,
60	                &used_args,
61	            );
62	        }
63	
64	        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
65	            if let Ok(value) = arg.to_value() {
66	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
67	                    current_cmd = next_cmd;
68	                    pos_index = 1;
69	                    used_args.clear();
70	                    continue;
71	                }
72	            }
73	        }
74	
75	        if is_escaped {
76	            (next_state, pos_index) =
77	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
78	        } else if arg.is_escape() {
79	            is_escaped = true;
80	            // Like the parser, `--` jumps straight to a `last(true)`
81	            // positional, skipping any unfilled positionals.
82	            if let Some(last_index) = current_cmd
83	                .get_positionals()
84	                .filter(|p| p.is_last_set())
85	                .filter_map(|p| p.get_index())
86	                .max()
87	            {
88	                pos_index = last_index;
89	            }
90	        } else if opt_allows_hyphen(&current_state, &arg) {
91	            match current_state {
92	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
93	                _ => unreachable!("else branch is only reachable in Opt state"),
94	            }
95	        } else if let Some((flag, value)) = arg.to_long() {
96	            if let Ok(flag) = flag {
97	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
98	
99	                if let Some(opt) = opt {
100	                    record_used_arg(&mut used_args, opt.get_id());
101	                    if opt.get_num_args().expect("built").takes_values() {
102	                        // An attached value (`--opt=value`) counts toward the
103	                        // option's values just like a space-separated one, so
104	                        // that completing after `--opt=value` sees the same
105	                        // state as completing after `--opt value`.
106	                        // An empty attached value (`--opt=`) types no value
107	                        // yet, so the option stays pending.
108	                        let count = value
109	                            .filter(|v| !v.is_empty())
110	                            .map(|v| attached_value_count(opt, v))
111	                            .unwrap_or(0);
112	                        next_state = parse_opt_value(opt, count);
113	                    };
114	                } else if pos_allows_hyphen(current_cmd, pos_index) {
115	                    (next_state, pos_index) =
116	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
117	                }
118	            }
119	        } else if let Some(short) = arg.to_short() {
120	            let (_, matched_opts, takes_value_opt, mut short) =
121	                parse_shortflags(current_cmd, short);
122	            for opt in &matched_opts {
123	                record_used_arg(&mut used_args, opt.get_id());
124	            }
125	            if let Some(opt) = takes_value_opt {
126	                // An attached value (`-ovalue`, `-o=value`) counts toward the
127	                // option's values just like a space-separated one. An empty
128	                // attached value (`-o=`) types no value yet, so the option
129	                // stays pending instead of being treated as satisfied.
130	                let count = short
131	                    .next_value_os()
132	                    .map(|v| v.strip_prefix("=").unwrap_or(v))
133	                    .filter(|v| !v.is_empty())
134	                    .map(|v| attached_value_count(opt, v))
135	                    .unwrap_or(0);
136	                next_state = parse_opt_value(opt, count);
137	            } else if pos_allows_hyphen(current_cmd, pos_index) {
138	                (next_state, pos_index) =
139	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
140	            }
141	        } else {
142	            match current_state {
143	                ParseState::ValueDone | ParseState::Pos(..) => {
144	                    (next_state, pos_index) =
145	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
146	                }
147	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
148	            }
149	        }
150	    }
151	
152	    Err(std::io::Error::other("no completion generated"))
153	}
