155	#[derive(Debug, PartialEq, Eq, Clone)]
156	enum ParseState<'a> {
157	    /// Parsing a value done, there is no state to record.
158	    ValueDone,
159	
160	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
161	    Pos((usize, usize)),
162	
163	    /// Parsing a optional flag argument
164	    Opt((&'a clap::Arg, usize)),
165	}
166	
167	fn complete_arg(
168	    arg: &clap_lex::ParsedArg<'_>,
169	    cmd: &clap::Command,
170	    current_dir: Option<&std::path::Path>,
171	    pos_index: usize,
172	    is_escaped: bool,
173	    state: ParseState<'_>,
174	    used_args: &[clap::Id],
175	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
176	    debug!(
177	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
178	        arg,
179	        cmd.get_name(),
180	        current_dir,
181	        pos_index,
182	        state
183	    );
184	    let mut completions = Vec::<CompletionCandidate>::new();
185	
186	    match state {
187	        ParseState::ValueDone => {
188	            if !is_escaped {
189	                if let Ok(value) = arg.to_value() {
190	                    completions.extend(complete_subcommand(value, cmd));
191	                }
192	            }
193	
194	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
195	                completions.extend(complete_arg_value(
196	                    arg.to_value(),
197	                    positional,
198	                    current_dir,
199	                    0,
200	                ));
201	            }
202	            if !is_escaped {
203	                completions.extend(complete_option(arg, cmd, current_dir));
204	            }
205	        }
206	        ParseState::Pos((_, num_arg)) => {
207	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
208	                completions.extend(complete_arg_value(
209	                    arg.to_value(),
210	                    positional,
211	                    current_dir,
212	                    num_arg.saturating_sub(1),
213	                ));
214	                if !is_escaped
215	                    && positional
216	                        .get_num_args()
217	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
218	                {
219	                    completions.extend(complete_option(arg, cmd, current_dir));
220	                }
221	            }
222	        }
223	        ParseState::Opt((opt, count)) => {
224	            completions.extend(complete_arg_value(
225	                arg.to_value(),
226	                opt,
227	                current_dir,
228	                count.saturating_sub(1),
229	            ));
230	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
231	            if count > min && can_switch_to_other_arg(opt, arg) {
232	                // The option's required values are satisfied and this word
233	                // would be parsed as a new flag rather than another value, so
234	                // also complete it as a positional, flag, option or subcommand.
235	                completions.extend(complete_arg(
236	                    arg,
237	                    cmd,
238	                    current_dir,
239	                    pos_index,
240	                    is_escaped,
241	                    ParseState::ValueDone,
242	                    used_args,
243	                )?);
244	            }
245	        }
246	    }
247	    filter_unavailable_args(&mut completions, cmd, used_args);
248	    if completions.iter().any(|a| !a.is_hide_set()) {
249	        completions.retain(|a| !a.is_hide_set());
250	    }
251	    dedup_argument_candidates(&mut completions, arg.is_empty());
252	
253	    let mut tags = Vec::new();
254	    for candidate in &completions {
255	        let tag = candidate.get_tag().cloned();
256	        if !tags.contains(&tag) {
257	            tags.push(tag);
258	        }
259	    }
260	    completions.sort_by_key(|c| {
261	        (
262	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
263	            c.get_display_order(),
264	        )
265	    });
266	
267	    Ok(completions)
268	}
