270	fn complete_option(
271	    arg: &clap_lex::ParsedArg<'_>,
272	    cmd: &clap::Command,
273	    current_dir: Option<&std::path::Path>,
274	) -> Vec<CompletionCandidate> {
275	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
276	    let mut completions = Vec::<CompletionCandidate>::new();
277	    if arg.is_empty() {
278	        completions.extend(longs_and_visible_aliases(cmd));
279	        completions.extend(hidden_longs_aliases(cmd));
280	
281	        let dash_or_arg = if arg.is_empty() {
282	            "-".into()
283	        } else {
284	            arg.to_value_os().to_string_lossy()
285	        };
286	        completions.extend(
287	            shorts_and_visible_aliases(cmd)
288	                .into_iter()
289	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
290	        );
291	    } else if arg.is_stdio() {
292	        // HACK: Assuming knowledge of is_stdio
293	        let dash_or_arg = if arg.is_empty() {
294	            "-".into()
295	        } else {
296	            arg.to_value_os().to_string_lossy()
297	        };
298	        completions.extend(
299	            shorts_and_visible_aliases(cmd)
300	                .into_iter()
301	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
302	        );
303	
304	        completions.extend(longs_and_visible_aliases(cmd));
305	        completions.extend(hidden_longs_aliases(cmd));
306	    } else if arg.is_escape() {
307	        // HACK: Assuming knowledge of is_escape
308	        completions.extend(longs_and_visible_aliases(cmd));
309	        completions.extend(hidden_longs_aliases(cmd));
310	    } else if let Some((flag, value)) = arg.to_long() {
311	        if let Ok(flag) = flag {
312	            if let Some(value) = value {
313	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
314	                    completions.extend(
315	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
316	                            .into_iter()
317	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
318	                    );
319	                }
320	            } else {
321	                completions.extend(
322	                    longs_and_visible_aliases(cmd)
323	                        .into_iter()
324	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
325	                );
326	                completions.extend(
327	                    hidden_longs_aliases(cmd)
328	                        .into_iter()
329	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
330	                );
331	            }
332	        }
333	    } else if let Some(short) = arg.to_short() {
334	        if !short.is_negative_number() {
335	            // Find the first takes_values option.
336	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
337	
338	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
339	            if let Some(opt) = takes_value_opt {
340	                let mut peek_short = short.clone();
341	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
342	                    short.next_flag();
343	                    true
344	                } else {
345	                    false
346	                };
347	
348	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
349	                completions.extend(
350	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
351	                        .into_iter()
352	                        .map(|comp| {
353	                            let sep = if has_equal { "=" } else { "" };
354	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
355	                        }),
356	                );
357	            } else {
358	                completions.extend(
359	                    shorts_and_visible_aliases(cmd)
360	                        .into_iter()
361	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
362	                );
363	            }
364	        }
365	    }
366	    debug!("complete_option: completions={completions:?}");
367	    completions
368	}
