370	fn complete_arg_value(
371	    value: Result<&str, &OsStr>,
372	    arg: &clap::Arg,
373	    current_dir: Option<&std::path::Path>,
374	    arg_index: usize,
375	) -> Vec<CompletionCandidate> {
376	    let mut values = Vec::new();
377	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
378	
379	    let (prefix, value) =
380	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
381	
382	    let value_os = match value {
383	        Ok(value) => OsStr::new(value),
384	        Err(value_os) => value_os,
385	    };
386	
387	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
388	        values.extend(completer.complete_at(arg_index, value_os));
389	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
390	        values.extend(complete_value_candidates(
391	            value_os,
392	            completer.value_candidates(),
393	        ));
394	    } else if let Some(possible_values) = possible_values(arg) {
395	        if let Ok(value) = value {
396	            values.extend(complete_candidates_str(
397	                value,
398	                possible_value_candidates(possible_values),
399	            ));
400	        }
401	    } else {
402	        match arg.get_value_hint() {
403	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
404	                // Should not complete
405	            }
406	            clap::ValueHint::AnyPath => {
407	                values.extend(complete_path(value_os, current_dir, &|_| true));
408	            }
409	            clap::ValueHint::FilePath => {
410	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
411	            }
412	            clap::ValueHint::DirPath => {
413	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
414	            }
415	            clap::ValueHint::ExecutablePath => {
416	                use is_executable::IsExecutable;
417	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
418	            }
419	            clap::ValueHint::CommandName
420	            | clap::ValueHint::CommandString
421	            | clap::ValueHint::CommandWithArguments
422	            | clap::ValueHint::Username
423	            | clap::ValueHint::Hostname
424	            | clap::ValueHint::Url
425	            | clap::ValueHint::EmailAddress => {
426	                // No completion implementation
427	            }
428	            _ => {
429	                // Safe-ish fallback
430	                values.extend(complete_path(value_os, current_dir, &|_| true));
431	            }
432	        }
433	
434	        values.sort();
435	    }
436	
437	    if let Some(prefix) = prefix {
438	        values = values
439	            .into_iter()
440	            .map(|comp| comp.add_prefix(prefix))
441	            .collect();
442	    }
443	    values = values
444	        .into_iter()
445	        .map(|comp| {
446	            if comp.get_tag().is_some() {
447	                comp
448	            } else {
449	                comp.tag(Some(arg.to_string().into()))
450	            }
451	        })
452	        .collect();
453	
454	    debug!("complete_arg_value: values={values:?}");
455	    values
456	}
457	
458	fn rsplit_delimiter<'s, 'o>(
459	    value: Result<&'s str, &'o OsStr>,
460	    delimiter: Option<char>,
461	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
462	    let delimiter = delimiter?;
463	    let value = value.ok()?;
464	    let pos = value.rfind(delimiter)?;
465	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
466	    Some((Some(prefix), Ok(value)))
467	}
