469	fn complete_value_candidates(
470	    value: &OsStr,
471	    completer: &dyn ValueCandidates,
472	) -> Vec<CompletionCandidate> {
473	    debug!("complete_value_candidates: value={value:?}");
474	
475	    let mut values = completer.candidates();
476	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
477	    values
478	}
479	
480	fn complete_candidates_str(
481	    value: &str,
482	    mut values: Vec<CompletionCandidate>,
483	) -> Vec<CompletionCandidate> {
484	    debug!("complete_candidates_str: value={value:?}");
485	
486	    values.retain(|comp| comp.get_value().starts_with(value));
487	    values
488	}
489	
490	fn complete_value_candidates_str(
491	    value: &str,
492	    completer: &dyn ValueCandidates,
493	) -> Vec<CompletionCandidate> {
494	    debug!("complete_value_candidates_str: value={value:?}");
495	
496	    complete_candidates_str(value, completer.candidates())
497	}
