499	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
500	    debug!(
501	        "complete_subcommand: cmd={:?}, value={:?}",
502	        cmd.get_name(),
503	        value
504	    );
505	
506	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
507	        .into_iter()
508	        .filter(|x| x.get_value().starts_with(value))
509	        .collect();
510	    if cmd.is_allow_external_subcommands_set() {
511	        let external_completer = cmd.get::<SubcommandCandidates>();
512	        if let Some(completer) = external_completer {
513	            scs.extend(complete_value_candidates_str(
514	                value,
515	                completer.value_candidates(),
516	            ));
517	        }
518	    }
519	
520	    scs.dedup();
521	    scs
522	}
