524	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
525	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
526	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
527	    debug!("longs: name={}", p.get_name());
528	
529	    p.get_arguments()
530	        .filter_map(|a| {
531	            a.get_long_and_visible_aliases().map(|longs| {
532	                longs
533	                    .into_iter()
534	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
535	            })
536	        })
537	        .flatten()
538	        .collect()
539	}
540	
541	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
542	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
543	    debug!("longs: name={}", p.get_name());
544	
545	    p.get_arguments()
546	        .filter_map(|a| {
547	            a.get_aliases().map(|longs| {
548	                longs.into_iter().map(|s| {
549	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
550	                })
551	            })
552	        })
553	        .flatten()
554	        .collect()
555	}
556	
557	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
558	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
559	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
560	    debug!("shorts: name={}", p.get_name());
561	
562	    p.get_arguments()
563	        .filter_map(|a| {
564	            a.get_short_and_visible_aliases().map(|shorts| {
565	                shorts.into_iter().map(|s| {
566	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
567	                        a.get_help()
568	                            .cloned()
569	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
570	                    )
571	                })
572	            })
573	        })
574	        .flatten()
575	        .collect()
576	}
577	
578	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
579	    candidate
580	        .help(arg.get_help().cloned())
581	        .id(Some(format!("arg::{}", arg.get_id())))
582	        .tag(Some(
583	            arg.get_help_heading()
584	                .unwrap_or("Options")
585	                .to_owned()
586	                .into(),
587	        ))
588	        .display_order(Some(arg.get_display_order()))
589	        .hide(arg.is_hide_set())
590	}
