592	/// Get the possible values for completion
593	fn possible_values(
594	    a: &clap::Arg,
595	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
596	    if !a.get_num_args().expect("built").takes_values() {
597	        None
598	    } else {
599	        a.get_value_parser().possible_values()
600	    }
601	}
