603	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
604	///
605	/// Subcommand `rustup toolchain install` would be converted to
606	/// `("install", "rustup toolchain install")`.
607	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
608	    debug!("subcommands: name={}", p.get_name());
609	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
610	    p.get_subcommands()
611	        .flat_map(|sc| {
612	            sc.get_name_and_visible_aliases()
613	                .into_iter()
614	                .map(|s| populate_command_candidate(s, p, sc))
615	                .chain(
616	                    sc.get_aliases()
617	                        .map(|s| populate_command_candidate(s, p, sc).hide(true)),
618	                )
619	        })
620	        .collect()
621	}
622	
623	fn populate_command_candidate(
624	    candidate_name: &str,
625	    cmd: &clap::Command,
626	    subcommand: &clap::Command,
627	) -> CompletionCandidate {
628	    CompletionCandidate::new(candidate_name.to_owned())
629	        .help(subcommand.get_about().cloned())
630	        .id(Some(format!("command::{candidate_name}")))
631	        .tag(Some(
632	            cmd.get_subcommand_help_heading()
633	                .unwrap_or("Commands")
634	                .to_owned()
635	                .into(),
636	        ))
637	        .display_order(Some(subcommand.get_display_order()))
638	        .hide(subcommand.is_hide_set())
639	}
640	
641	/// Parse the short flags and find the first `takes_values` option.
642	///
643	/// Returns the raw leading flags, every matched argument, the first
644	/// `takes_values` option (if any), and the remaining unparsed flags.
645	fn parse_shortflags<'c, 's>(
646	    cmd: &'c clap::Command,
647	    mut short: clap_lex::ShortFlags<'s>,
648	) -> (
649	    String,
650	    Vec<&'c clap::Arg>,
651	    Option<&'c clap::Arg>,
652	    clap_lex::ShortFlags<'s>,
653	) {
654	    let takes_value_opt;
655	    let mut matched_opts = Vec::new();
656	    let mut leading_flags = String::new();
657	    // Find the first takes_values option.
658	    loop {
659	        match short.next_flag() {
660	            Some(Ok(opt)) => {
661	                leading_flags.push(opt);
662	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
663	                if let Some(opt) = opt {
664	                    matched_opts.push(opt);
665	                }
666	                if opt
667	                    .map(|o| o.get_num_args().expect("built").takes_values())
668	                    .unwrap_or(false)
669	                {
670	                    takes_value_opt = opt;
671	                    break;
672	                }
673	            }
674	            Some(Err(_)) | None => {
675	                takes_value_opt = None;
676	                break;
677	            }
678	        }
679	    }
680	
681	    (leading_flags, matched_opts, takes_value_opt, short)
682	}
683	
684	/// Whether the argument can be addressed by the long flag `flag`,
685	/// including visible and hidden aliases.
686	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
687	    arg.get_long() == Some(flag)
688	        || arg
689	            .get_all_aliases()
690	            .is_some_and(|aliases| aliases.contains(&flag))
691	}
692	
693	/// Whether the argument can be addressed by the short flag `flag`,
694	/// including visible and hidden aliases.
695	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
696	    arg.get_short() == Some(flag)
697	        || arg
698	            .get_all_short_aliases()
699	            .is_some_and(|aliases| aliases.contains(&flag))
700	}
701	
702	/// Remove argument candidates that are unavailable given the arguments
703	/// already present on the command line.
704	///
705	/// Two rules apply:
706	/// - Non-multiple argument groups: once any member of such a group is on the
707	///   command line, every member of that group (including the selected one and
708	///   all of its aliases) is removed, mirroring the parser's one-of constraint.
709	/// - Explicit conflicts: a candidate that conflicts with an already-used
710	///   argument is removed; conflicts only need to be declared on one side.
711	///
712	/// Anything that is not an argument candidate (positional values,
713	/// subcommands, custom candidates) is left untouched.
714	fn filter_unavailable_args(
715	    completions: &mut Vec<CompletionCandidate>,
716	    cmd: &clap::Command,
717	    used_args: &[clap::Id],
718	) {
719	    if used_args.is_empty() {
720	        return;
721	    }
722	
723	    // Members of non-multiple groups that already have a member present.
724	    let mut excluded_by_group = std::collections::HashSet::<clap::Id>::new();
725	    for group in cmd.get_groups().filter(|group| !group.is_multiple_set()) {
726	        let members: Vec<&clap::Id> = group.get_args().collect();
727	        if members
728	            .iter()
729	            .any(|id| used_args.iter().any(|used| used == *id))
730	        {
731	            excluded_by_group.extend(members.into_iter().cloned());
732	        }
733	    }
734	
735	    completions.retain(|candidate| {
736	        let Some(arg) = candidate
737	            .get_id()
738	            .and_then(|id| id.strip_prefix("arg::"))
739	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
740	        else {
741	            return true;
742	        };
743	        if excluded_by_group.contains(arg.get_id()) {
744	            return false;
745	        }
746	        !used_args.iter().any(|used_id| {
747	            cmd.get_arguments()
748	                .find(|a| a.get_id() == used_id)
749	                .is_some_and(|used| args_conflict(cmd, arg, used))
750	        })
751	    });
752	}
753	
754	/// Record an argument seen on the command line, keeping the first occurrence
755	/// only so that repeating a flag neither alters filtering nor restores
756	/// candidates already excluded.
757	fn record_used_arg(used_args: &mut Vec<clap::Id>, id: &clap::Id) {
758	    if !used_args.iter().any(|used| used == id) {
759	        used_args.push(id.clone());
760	    }
761	}
762	
763	/// De-duplicate flag candidates.
764	///
765	/// With an empty word every long spelling of an argument (its long name and
766	/// visible aliases) is offered, while short spellings are still collapsed to
767	/// the canonical short and dropped for arguments that also have a long form.
768	/// Once a prefix is typed at most one spelling of an argument can match, so
769	/// candidates are de-duplicated by argument id as before.
770	fn dedup_argument_candidates(completions: &mut Vec<CompletionCandidate>, empty_word: bool) {
771	    if empty_word {
772	        let long_ids: std::collections::HashSet<String> = completions
773	            .iter()
774	            .filter(|candidate| {
775	                candidate.get_id().is_some() && candidate.get_value().starts_with("--")
776	            })
777	            .filter_map(|candidate| candidate.get_id().cloned())
778	            .collect();
779	        let mut seen_short_ids = std::collections::HashSet::new();
780	        completions.retain(|candidate| {
781	            let Some(id) = candidate.get_id() else {
782	                return true;
783	            };
784	            if candidate.get_value().starts_with("--") {
785	                // Keep the long name and every visible alias.
786	                true
787	            } else if long_ids.contains(id) {
788	                // Prefer the long forms over the short ones.
789	                false
790	            } else {
791	                seen_short_ids.insert(id.clone())
792	            }
793	        });
794	    } else {
795	        let mut seen_ids = std::collections::HashSet::new();
796	        completions.retain(|candidate| {
797	            if let Some(id) = candidate.get_id().cloned() {
798	                seen_ids.insert(id)
799	            } else {
800	                true
801	            }
802	        });
803	    }
804	}
805	
806	/// Whether `first` and `second` conflict, no matter which one declares it.
807	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
808	    cmd.get_arg_conflicts_with(first)
809	        .iter()
810	        .any(|c| c.get_id() == second.get_id())
811	        || cmd
812	            .get_arg_conflicts_with(second)
813	            .iter()
814	            .any(|c| c.get_id() == first.get_id())
815	}
816	
817	/// The positional the parser would fill at `pos_index`.
818	///
819	/// A `last(true)` positional only exists after `--`; before the terminator
820	/// the parser rejects values for it, so it must not be completed.
821	fn find_positional(cmd: &clap::Command, pos_index: usize, is_escaped: bool) -> Option<&clap::Arg> {
822	    cmd.get_positionals()
823	        .find(|p| p.get_index() == Some(pos_index) && (is_escaped || !p.is_last_set()))
824	}
825	
826	/// Parse the positional arguments. Return the new state and the new positional index.
827	fn parse_positional<'a>(
828	    cmd: &clap::Command,
829	    pos_index: usize,
830	    is_escaped: bool,
831	    state: ParseState<'a>,
832	) -> (ParseState<'a>, usize) {
833	    let pos_arg = cmd
834	        .get_positionals()
835	        .find(|p| p.get_index() == Some(pos_index));
836	    let num_args = pos_arg
837	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
838	        .unwrap_or(1);
839	
840	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
841	        if num_args > 1 {
842	            (ParseState::Pos((pos_index, 1)), pos_index)
843	        } else {
844	            if is_escaped {
845	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
846	            } else {
847	                (ParseState::ValueDone, pos_index + 1)
848	            }
849	        }
850	    };
851	    match state {
852	        ParseState::ValueDone => {
853	            update_state_with_new_positional(pos_index)
854	        },
855	        ParseState::Pos((prev_pos_index, num_arg)) => {
856	            if prev_pos_index == pos_index {
857	                if num_arg + 1 < num_args {
858	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
859	                } else {
860	                    if is_escaped {
861	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
862	                    } else {
863	                        (ParseState::ValueDone, pos_index + 1)
864	                    }
865	                }
866	            } else {
867	                update_state_with_new_positional(pos_index)
868	            }
869	        }
870	        ParseState::Opt(..) => unreachable!(
871	            "This branch won't be hit,
872	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
873	        ),
874	    }
875	}
876	
877	/// Parse optional flag argument. Return new state
878	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
879	    let range = opt.get_num_args().expect("built");
880	    let max = range.max_values();
881	    if count < max {
882	        ParseState::Opt((opt, count + 1))
883	    } else {
884	        ParseState::ValueDone
885	    }
886	}
887	
888	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
889	/// for, honoring the value delimiter.
890	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
891	    match (opt.get_value_delimiter(), value.to_str()) {
892	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
893	        _ => 1,
894	    }
895	}
896	
897	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
898	    cmd.get_positionals()
899	        .find(|a| a.get_index() == Some(pos_index))
900	        .map(|p| p.is_allow_hyphen_values_set())
901	        .unwrap_or(false)
902	}
903	
904	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
905	    let val = arg.to_value_os();
906	    if val.starts_with("-") {
907	        if let ParseState::Opt((opt, _)) = state {
908	            return opt.is_allow_hyphen_values_set();
909	        }
910	    }
911	
912	    false
913	}
914	
915	/// Whether a word can terminate a still-open multi-value option and start a
916	/// new argument instead, the way the parser would read it.
917	///
918	/// While an option still owes values, the parser greedily consumes every plain
919	/// word as one of its values; only flag-like words can switch to another
920	/// argument. An option that accepts hyphen values consumes those too.
921	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
922	    if arg.is_escape() {
923	        // `--` cancels every pending option unless its values may start with `--`.
924	        return !pending.is_allow_hyphen_values_set();
925	    }
926	    if !arg.to_value_os().starts_with("-") {
927	        // A plain word is always another value of the pending option.
928	        return false;
929	    }
930	    if pending.is_allow_hyphen_values_set() {
931	        return false;
932	    }
933	    // `-` is a stdio/value, not a flag.
934	    if arg.is_stdio() {
935	        return false;
936	    }
937	    // Both long and short flag styles can start a new argument; unknown flags
938	    // still switch (and error during parsing) rather than become option values.
939	    arg.to_long().is_some() || arg.to_short().is_some()
940	}
