#[test]
fn multiple_value_terminator_option() {
    let mut cmd = Command::new("lip")
        .arg(
            Arg::new("files")
                .short('f')
                .value_terminator(";")
                .action(ArgAction::Set)
                .num_args(0..),
        )
        .arg(Arg::new("other"))
        .arg(Arg::new("stop").short('X').action(ArgAction::SetTrue));

    // Terminated
    let m = cmd.try_get_matches_from_mut(vec!["lip", "-f", ";", "otherval"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(m.contains_id("files"));
    assert!(m.contains_id("other"));
    assert!(!m.get_flag("stop"));
    assert_eq!(
        m.get_many::<String>("files")
            .unwrap()
            .map(|v| v.as_str())
            .collect::<Vec<_>>(),
        Vec::<String>::new(),
    );
    assert_eq!(
        m.get_one::<String>("other").map(|v| v.as_str()),
        Some("otherval")
    );

    let m = cmd.try_get_matches_from_mut(vec!["lip", "-f", "val1", "val2", ";", "otherval"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(m.contains_id("files"));
    assert!(m.contains_id("other"));
    assert!(!m.get_flag("stop"));
    assert_eq!(
        m.get_many::<String>("files")
            .unwrap()
            .map(|v| v.as_str())
            .collect::<Vec<_>>(),
        ["val1", "val2"]
    );
    assert_eq!(
        m.get_one::<String>("other").map(|v| v.as_str()),
        Some("otherval")
    );

    // Unterminated
    let m = cmd.try_get_matches_from_mut(vec!["lip", "-f"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(m.contains_id("files"));
    assert!(!m.contains_id("other"));
    assert!(!m.get_flag("stop"));
    assert_eq!(
        m.get_many::<String>("files")
            .unwrap()
            .map(|v| v.as_str())
            .collect::<Vec<_>>(),
        Vec::<String>::new(),
    );

    let m = cmd.try_get_matches_from_mut(vec!["lip", "-f", "val1", "val2"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(m.contains_id("files"));
    assert!(!m.contains_id("other"));
    assert!(!m.get_flag("stop"));
    assert_eq!(
        m.get_many::<String>("files")
            .unwrap()
            .map(|v| v.as_str())
            .collect::<Vec<_>>(),
        ["val1", "val2"]
    );

    // Terminated by flag
    let m = cmd.try_get_matches_from_mut(vec!["lip", "-f", "-X", "otherval"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(m.contains_id("files"));
    assert!(m.contains_id("other"));
    assert!(m.get_flag("stop"));
    assert_eq!(
        m.get_many::<String>("files")
            .unwrap()
            .map(|v| v.as_str())
            .collect::<Vec<_>>(),
        Vec::<String>::new(),
    );
    assert_eq!(
        m.get_one::<String>("other").map(|v| v.as_str()),
        Some("otherval")
    );

    let m = cmd.try_get_matches_from_mut(vec!["lip", "-f", "val1", "val2", "-X", "otherval"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(m.contains_id("files"));
    assert!(m.contains_id("other"));
    assert!(m.get_flag("stop"));
    assert_eq!(
        m.get_many::<String>("files")
            .unwrap()
            .map(|v| v.as_str())
            .collect::<Vec<_>>(),
        ["val1", "val2"]
    );
    assert_eq!(
        m.get_one::<String>("other").map(|v| v.as_str()),
        Some("otherval")
    );
}

#[test]
fn multiple_value_terminator_positional() {
    let mut cmd = Command::new("lip")
        .arg(
            Arg::new("files")
                .value_terminator(";")
                .action(ArgAction::Set)
                .num_args(0..),
        )
        .arg(Arg::new("other"))
        .arg(Arg::new("stop").short('X').action(ArgAction::SetTrue));

    // Terminated
    let m = cmd.try_get_matches_from_mut(vec!["lip", ";", "otherval"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(!m.contains_id("files"));
    assert!(m.contains_id("other"));
    assert!(!m.get_flag("stop"));
    assert_eq!(
        m.get_one::<String>("other").map(|v| v.as_str()),
        Some("otherval")
    );

    let m = cmd.try_get_matches_from_mut(vec!["lip", "val1", "val2", ";", "otherval"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(m.contains_id("files"));
    assert!(m.contains_id("other"));
    assert!(!m.get_flag("stop"));
    assert_eq!(
        m.get_many::<String>("files")
            .unwrap()
            .map(|v| v.as_str())
            .collect::<Vec<_>>(),
        ["val1", "val2"]
    );
    assert_eq!(
        m.get_one::<String>("other").map(|v| v.as_str()),
        Some("otherval")
    );

    // Unterminated
    let m = cmd.try_get_matches_from_mut(vec!["lip"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(!m.contains_id("files"));
    assert!(!m.contains_id("other"));
    assert!(!m.get_flag("stop"));

    let m = cmd.try_get_matches_from_mut(vec!["lip", "val1", "val2"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(m.contains_id("files"));
    assert!(!m.contains_id("other"));
    assert!(!m.get_flag("stop"));
    assert_eq!(
        m.get_many::<String>("files")
            .unwrap()
            .map(|v| v.as_str())
            .collect::<Vec<_>>(),
        ["val1", "val2"]
    );

    // Terminated by flag
    let m = cmd.try_get_matches_from_mut(vec!["lip", "-X", "otherval"]);
    assert!(m.is_ok(), "{}", m.unwrap_err());
    let m = m.unwrap();
    assert!(m.contains_id("files"));
    assert!(!m.contains_id("other"));
    assert!(m.get_flag("stop"));
    assert_eq!(
        m.get_many::<String>("files")
            .unwrap()
            .map(|v| v.as_str())
            .collect::<Vec<_>>(),
        ["otherval"]
    );

    let m = cmd.try_get_matches_from_mut(vec!["lip", "val1", "val2", "-X", "otherval"]);
    assert!(m.is_err());
    let err = m.unwrap_err();
    utils::assert_error(
        err,
        ErrorKind::ArgumentConflict,
        str![[r#"
error: the argument '[files]...' cannot be used multiple times

Usage: lip [OPTIONS] [files]... [other]

For more information, try '--help'.

"#]],
        true,
    );
}

#[test]
fn multiple_vals_with_hyphen() {
    let res = Command::new("do")
        .arg(
            Arg::new("cmds")
                .action(ArgAction::Set)
                .num_args(1..)
                .allow_hyphen_values(true)
                .value_terminator(";"),
        )
        .arg(Arg::new("location"))
        .try_get_matches_from(vec![
            "do",
            "find",
            "-type",
            "f",
            "-name",
            "special",
            ";",
            "/home/clap",
        ]);
    assert!(res.is_ok(), "{:?}", res.unwrap_err().kind());

    let m = res.unwrap();
    let cmds: Vec<_> = m
        .get_many::<String>("cmds")
        .unwrap()
        .map(|v| v.as_str())
        .collect();
    assert_eq!(&cmds, &["find", "-type", "f", "-name", "special"]);
    assert_eq!(
        m.get_one::<String>("location").map(|v| v.as_str()),
        Some("/home/clap")
    );
}

